package edu.ku.commerce.omnichannel_commerce.common.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.*; import java.util.*; import org.springframework.security.authentication.*; import org.springframework.security.core.authority.*; import org.springframework.security.core.context.*; import org.springframework.stereotype.*; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; public JwtFilter(JwtService jwt){this.jwt=jwt;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException {String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var cl=jwt.claims(h.substring(7));var auth=new UsernamePasswordAuthenticationToken(cl.getSubject(),null,List.of(new SimpleGrantedAuthority("ROLE_"+cl.get("role",String.class))));SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception ignored){}c.doFilter(r,s);} }
